using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
internal static class CraftReminderPreferences {
 static readonly object Gate=new object();
 static string FileName(string root){root=CraftSetupPaths.NormalizeFolder(root);string file=Path.Combine(root,"state","update-preferences.json");for(string current=Path.GetDirectoryName(file);!String.IsNullOrEmpty(current);current=Path.GetDirectoryName(current))if(Directory.Exists(current)&&(File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new IOException("Craft 提醒目录包含链接");if(File.Exists(file)&&(File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("Craft 提醒文件包含链接");return file;}
 static string Text(Dictionary<string,object> value,string key){object item;return value.TryGetValue(key,out item)&&item!=null?Convert.ToString(item):"";}
 static Version Parse(string version){if(!Regex.IsMatch(version??"",@"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)c$"))throw new ArgumentException("Craft 提醒版本无效");var parsed=new Version(version.Substring(0,version.Length-1));if(new[]{parsed.Major,parsed.Minor,parsed.Build,parsed.Revision}.Any(part=>part>65535))throw new ArgumentException("Craft 提醒版本越界");return parsed;}
 static Dictionary<string,object> Default(){return new Dictionary<string,object>{{"schemaVersion",1},{"product","craft"},{"mode","on"},{"baselineVersion",""}};}
 internal static Dictionary<string,object> Read(string root){lock(Gate){string file=FileName(root);if(!File.Exists(file))return Default();if(new FileInfo(file).Length>4096)throw new IOException("Craft 提醒设置过大");var value=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));if(value==null||Text(value,"schemaVersion")!="1"||Text(value,"product")!="craft")throw new IOException("Craft 提醒产品不匹配");string mode=Text(value,"mode");if(!new[]{"on","next-release","next-major","never"}.Contains(mode))throw new IOException("Craft 提醒设置无效");if(mode=="next-release"||mode=="next-major")Parse(Text(value,"baselineVersion"));return value;}}
 internal static Dictionary<string,object> Save(string root,string mode,string baseline){if(!new[]{"on","next-release","next-major","never"}.Contains(mode))throw new ArgumentException("Craft 提醒选项无效");if(mode=="next-release"||mode=="next-major")Parse(baseline);var value=Default();value["mode"]=mode;value["baselineVersion"]=mode=="on"?"":baseline;lock(Gate){string file=FileName(root);Directory.CreateDirectory(Path.GetDirectoryName(file));string temp=file+".tmp-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,new JavaScriptSerializer().Serialize(value));if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}finally{if(File.Exists(temp))File.Delete(temp);}}return value;}
 internal static bool Suppressed(Dictionary<string,object> preference,string latest){string mode=Text(preference,"mode");if(mode=="never")return true;if(mode=="on")return false;Version available=Parse(latest),baseline=Parse(Text(preference,"baselineVersion"));return mode=="next-release"?available<=baseline:available.Major<=baseline.Major;}
}
